//! The live-measurement modules against the committed artifacts and the Python.
//!
//! Scoring (`score_live`, `live_rank score [rich]`) reads the committed tasks, keys and model answers and must write
//! the committed result files byte for byte.
//!
//! The task builders cannot be held to the committed task files: those were generated by older code and are frozen
//! because the recorded model answers refer to their item ids.  `live_tasks.json`/`live_key.json` come from
//! c6ba738, before 80891f8 ("unique pattern anchors") changed the corpus generator; the `live_rank_*` files come
//! from 36f0c30, before 960b2f0 raised the calibrated `question_frac` from 0.25 to 0.65 (and later calibration
//! changes).  The Python at f7e954b/84a128d writes different files, so the builders are held to the SHA-256 of what
//! that Python writes:
//!
//! ```text
//! PYTHONPATH=. python -m research.mycelic.live_tasks
//! PYTHONPATH=. python -m research.mycelic.live_rank
//! PYTHONPATH=. python -m research.mycelic.live_rank rich
//! ```
//!
//! run in a scratch checkout of 84a128d (numpy 2.4.6), then `shasum -a 256` of the four task/key files.

use mycelic_research::runner::{Cal, repo_root};
use mycelic_research::{live_rank, live_tasks, score_live};
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};

fn committed_art() -> PathBuf {
    repo_root().join("research").join("mycelic").join("artifacts")
}

fn committed_keys() -> PathBuf {
    repo_root().join("research").join("mycelic").join("keys")
}

fn read(path: &Path) -> Vec<u8> {
    std::fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn sha256_hex(path: &Path) -> String {
    hex::encode(Sha256::digest(read(path)))
}

/// Byte equality with a readable failure: the first differing line.
fn assert_same_bytes(got: &Path, want: &Path) {
    let (g, w) = (read(got), read(want));
    if g != w {
        let (gs, ws) = (String::from_utf8_lossy(&g), String::from_utf8_lossy(&w));
        let line =
            gs.lines().zip(ws.lines()).position(|(a, b)| a != b).unwrap_or(gs.lines().count().min(ws.lines().count()));
        panic!(
            "{} differs from {} at line {}:\n  got:  {:?}\n  want: {:?}",
            got.display(),
            want.display(),
            line + 1,
            gs.lines().nth(line),
            ws.lines().nth(line)
        );
    }
}

#[test]
fn score_live_reproduces_the_committed_calibration() {
    let out = tempfile::tempdir().unwrap();
    score_live::run(&committed_art(), &committed_keys(), out.path()).unwrap();
    assert_same_bytes(&out.path().join("live_calibration.json"), &committed_art().join("live_calibration.json"));
}

#[test]
fn live_rank_score_reproduces_the_committed_results() {
    let out = tempfile::tempdir().unwrap();
    for (rich, file) in [(false, "live_rank_results.json"), (true, "live_rank_results_rich.json")] {
        live_rank::score(rich, &committed_art(), &committed_keys(), out.path()).unwrap();
        assert_same_bytes(&out.path().join(file), &committed_art().join(file));
    }
}

/// The `*.sha256` manifests next to the task files still describe the committed task files.
#[test]
fn committed_task_manifests_match() {
    for manifest in ["live_tasks.sha256", "live_rank_tasks.sha256"] {
        let text = String::from_utf8(read(&committed_art().join(manifest))).unwrap();
        for line in text.lines().filter(|l| !l.trim().is_empty()) {
            let (hash, path) = line.split_once("  ").expect("`<sha256>  <path>` lines");
            assert_eq!(sha256_hex(&repo_root().join(path)), hash, "{manifest}: {path}");
        }
    }
}

#[test]
fn live_tasks_build_matches_the_python() {
    let (art, keys) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
    live_tasks::build(900, 2000, art.path(), keys.path()).unwrap();
    assert_eq!(
        sha256_hex(&art.path().join("live_tasks.json")),
        "cfc9be59661e00cc6a8e68fb0bee9a056374b2621207c8626a12e50f144c73b9"
    );
    assert_eq!(
        sha256_hex(&keys.path().join("live_key.json")),
        "cef2d8f9732bde799f0cffb3399f461bf33c2e3ffd417eb522221a74348bfacf"
    );
}

#[test]
fn live_rank_build_matches_the_python() {
    let cal = Cal::from_path(&committed_art().join("calibration.json"));
    let (art, keys) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
    let cases = [
        (false, "", "497b18259aee8ceaf0bfc2f8f654509a331a0cfa3ee3cdf1484c399fc59976b8"),
        (true, "_rich", "0f480daa6e4e613c041f0376f0de63d48b7b254e7b1a34ac1fde1f310088ec01"),
    ];
    for (rich, suffix, tasks_sha) in cases {
        live_rank::build(901, 10_000, rich, &cal, art.path(), keys.path()).unwrap();
        assert_eq!(sha256_hex(&art.path().join(format!("live_rank_tasks{suffix}.json"))), tasks_sha, "rich={rich}");
        // the key does not depend on `rich`
        assert_eq!(
            sha256_hex(&keys.path().join(format!("live_rank_key{suffix}.json"))),
            "3bd8237923fa3b6a8e4f590c50116cf0722a79c06978361064727620bd28922b",
            "rich={rich}"
        );
    }
}
